few_shot_examples.query:
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?title
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasTitle ?title .
}

PREFIX coress-ont: <http://www.semanticweb.org/ontologies/2024/metadata-schema/>
SELECT DISTINCT ?author ?agent ?publication
WHERE {
  ?publication coress-ont:submittedBy ?author .
  OPTIONAL { ?agent coress-ont:performsRole ?author . }
  FILTER NOT EXISTS { ?agent coress-ont:hasEmailAddress ?email }
}

